require "rails_helper"
require "json"

# Conformance (formal/INTEGRATION.md, layer 3): formal/fixtures/plugin_deletion.json
# is PluginDeletion.decide_with_unknowns on three nodes (owned by core, plugin
# p0 and plugin p1) over every edge set, both dependency shapes, both deletion
# targets and every single unresolved node, generated by
# `lake exe syrus_fixtures plugin_deletion`. This runs the real
# Formal::PluginDeletion.verdict on the same graphs. The model proves that a
# `safe` verdict means the reduced system reaches nothing that was deleted
# (`safe_means_closed`), so agreement here is what lets the edge scan stand in
# for booting a reduced tree.
RSpec.describe "PluginDeletion model conformance" do
  fixture = JSON.parse(Rails.root.join("formal/fixtures/plugin_deletion.json").read)

  it "covers every combination" do
    expect(fixture.fetch("cases").size).to eq(2 * 2 * 64 * 4)
  end

  it "agrees with the model on every case" do
    disagreements = fixture.fetch("cases").reject do |example|
      owners = example.fetch("owners").each_with_index.to_h { |owner, node| [ node, owner == "core" ? Formal::PluginDeletion::CORE : owner ] }
      verdict = Formal::PluginDeletion.verdict(
        owner: owners, edges: example.fetch("edges"), removed: example.fetch("removed"),
        unknown_from: example.fetch("unknown_from")
      )
      verdict.to_s == example.fetch("verdict")
    end

    expect(disagreements).to be_empty, "#{disagreements.size} disagreements, first: #{disagreements.first.inspect}"
  end

  it "removes the same plugins the audit removes for the dependency shapes it models" do
    audit = Admin::PluginSourceBoundaryAudit.new(root: Rails.root, manifests: [
      Syrus::Plugin::Manifest.new(name: "p0", version: "0.0.0", provides: {}, metadata: {}, depends_on: [],
        default_enabled: true, disableable: true, experimental: false, requires_syrus: nil),
      Syrus::Plugin::Manifest.new(name: "p1", version: "0.0.0", provides: {}, metadata: {}, depends_on: [ "p0" ],
        default_enabled: true, disableable: true, experimental: false, requires_syrus: nil)
    ])
    allow(audit).to receive(:bundled_manifest_names).and_return(%w[p0 p1])
    dependent = fixture.fetch("cases").find { |c| c.fetch("dependent") && c.fetch("target") == "p0" }

    expect(audit.removed_plugin_names_for("p0").sort).to eq(dependent.fetch("removed").sort)
    expect(audit.removed_plugin_names_for("p1")).to eq([ "p1" ])
  end
end
